"""Sort List — bottom-up-free merge sort on the linked list.

Split at the middle with fast/slow pointers, sort both halves, merge. Recursion
depth is log n, so the "constant space" version only differs by the stack.

Time: O(n log n)   Space: O(log n)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def sortList(self, head):
        if not head or not head.next:
            return head
        slow, fast = head, head.next
        while fast and fast.next:
            slow, fast = slow.next, fast.next.next
        mid, slow.next = slow.next, None

        left, right = self.sortList(head), self.sortList(mid)
        sentinel = ListNode()
        tail = sentinel
        while left and right:
            if left.val <= right.val:
                tail.next, left = left, left.next
            else:
                tail.next, right = right, right.next
            tail = tail.next
        tail.next = left or right
        return sentinel.next
